const cultivos = $('Obtener Cultivos Activos').all();
const todasEtapas = $('Obtener Orden Etapas').all().map(i => i.json);
// 16.24 — Detección de truncado silencioso. `Obtener Orden Etapas` pide limit=1000;
// si vuelve exactamente esa cantidad estamos en el borde y el catálogo puede estar
// incompleto. Un catálogo truncado no da error: hace que findIndex no encuentre la
// etapa actual (skip silencioso, B.2), o que la última etapa presente parezca la
// terminal y el cultivo deje de evaluarse para siempre.
const LIMITE_CATALOGO = 1000;
if (todasEtapas.length >= LIMITE_CATALOGO) {
  throw new Error(
    `Obtener Orden Etapas devolvió ${todasEtapas.length} filas, que es el tope de la query. ` +
    `El catálogo de etapas puede estar truncado y cualquier decisión de avance sería inválida. ` +
    `Subir el limit o paginar.`
  );
}
const resultados = [];

for (const item of cultivos) {
  const cultivo = item.json;

  const etapasEspecie = todasEtapas
    .filter(e => e.especie_id === cultivo.especie_id)
    .sort((a, b) => a.orden - b.orden);

  const idxActual = etapasEspecie.findIndex(e => e.tipo_etapa?.nombre_etapa === cultivo.etapa_actual);
  if (idxActual === -1) continue; // etapa actual no encontrada en el catálogo de la especie - caso raro, se omite

  const fechaInicioEtapa = new Date(cultivo.fecha_inicio_etapa);
  const hoy = new Date();
  const diasEnEtapa = Math.floor(Math.abs(hoy - fechaInicioEtapa) / (1000 * 60 * 60 * 24));
  const ventanaEvaluacion = cultivo.duracion_estimada_dias * 0.8;
  const hayEtapaSiguiente = idxActual < etapasEspecie.length - 1;

  if (hayEtapaSiguiente && diasEnEtapa >= ventanaEvaluacion) {
    const siguiente = etapasEspecie[idxActual + 1];
    // La etapa siguiente no puede ser la actual. Si lo es, el catálogo vino mal
    // (duplicado, mal ordenado) y cualquier decisión sobre él sería inválida.
    if (siguiente.id === cultivo.etapas_especie_id) {
      throw new Error(
        `Catálogo inválido para ${cultivo.planta}: la etapa siguiente a "${cultivo.etapa_actual}" ` +
        `resolvió a sí misma (etapas_especie_id ${siguiente.id}). Revisar duplicados en Obtener Orden Etapas.`
      );
    }
    // 16.42 — El criterio visual de cada etapa vive en el catálogo, no en el
    // prompt. Validación positiva: si falta, el prompt saldría con un hueco y el
    // modelo decidiría sin criterio. Con NOT NULL en la base, esto solo puede
    // pasar si `Obtener Orden Etapas` deja de pedir la columna (drift).
    const actual = etapasEspecie[idxActual];
    for (const [rol, etapa] of [['actual', actual], ['siguiente', siguiente]]) {
      if (typeof etapa.criterio_visual !== 'string' || etapa.criterio_visual.trim() === '') {
        throw new Error(
          `Falta criterio_visual de la etapa ${rol} ("${etapa.tipo_etapa?.nombre_etapa}") para ${cultivo.planta}. ` +
          `Revisar que Obtener Orden Etapas pida la columna en su select.`
        );
      }
    }
    resultados.push({
      json: {
        ...cultivo,
        criterio_etapa_actual: actual.criterio_visual,
        criterio_etapa_siguiente: siguiente.criterio_visual,
        etapa_siguiente: siguiente.tipo_etapa.nombre_etapa,
        etapa_siguiente_id: siguiente.etapa_id,
        etapa_siguiente_etapas_especie_id: siguiente.id,
        indice_etapa_actual: idxActual,
        dias_en_etapa: diasEnEtapa
      }
    });
  }
}

if (resultados.length === 0) {
  resultados.push({ json: { skip: true } });
}

return resultados;

