// ============================================================
// WF3 · Nodo "Parsear y decidir"
// 16.14 (validación de forma) + 16.20 (validación de contenido)
// + 16.22 (guarda reapuntada) + 16.25 (arma el contrato de la RPC)
// ============================================================

// Un ítem por cultivo. El nodo HTTP preserva orden y cardinalidad incluso al
// fallar, porque `onError: continueRegularOutput` emite un ítem de error en la
// misma posición.
//
// 16.22 — La guarda empareja contra `Foto Descargada` y NO contra
// `Convertir a Base64`: al agregar un filtro a la cadena, el conjunto correcto
// es el que efectivamente entró a Gemini.
const respuestas = $input.all();
const cultivos = $('Foto Descargada').all();

if (respuestas.length !== cultivos.length) {
  throw new Error(
    `Desalineación en Parsear y decidir: ${respuestas.length} respuestas para ${cultivos.length} cultivos ` +
    `que pasaron el filtro de foto.`
  );
}

// 16.20 — Normalización de nombres de etapa: fuera acentos, mayúsculas y
// espacios, de los DOS lados. "Floración", "floracion" y "Floracion " son la
// misma etapa del dominio.
// El rango se escribe escapado (\u0300-\u036f) y no con los caracteres
// literales: son diacríticos combinantes, invisibles en un editor, y una
// copia/pega los puede alterar sin que se vea.
const normalizar = (t) => String(t ?? '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().trim();

return respuestas.map((item, i) => {
  const geminiResponse = item.json;
  const cultivoData = cultivos[i].json;

  // Validación POSITIVA de FORMA (16.14): confirmar que la respuesta contiene
  // lo que se espera, en vez de asumir que "no falló" equivale a "es un diagnóstico".
  let diagnosis;
  const rawText = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text;

  if (!rawText) {
    diagnosis = {
      cambio_confirmado: false,
      confianza: 0,
      evidencia_visual: null,
      justificacion: 'La IA no pudo analizar la foto en este intento.',
      diagnostico_fallido: true
    };
  } else {
    try {
      const cleaned = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
      diagnosis = JSON.parse(cleaned);
      diagnosis.diagnostico_fallido = false;
    } catch (e) {
      diagnosis = {
        cambio_confirmado: false,
        confianza: 0,
        evidencia_visual: null,
        justificacion: 'La IA respondió en un formato inesperado.',
        diagnostico_fallido: true
      };
    }
  }

  // Validación POSITIVA de CONTENIDO (16.20), un nivel más adentro:
  // que la respuesta esté bien formada no significa que responda la pregunta
  // que se hizo. El prompt pregunta por `etapa_siguiente`; si la IA nombra
  // otra etapa, su `cambio_confirmado` no se refiere a esta transición.
  const etapaDetectada = normalizar(diagnosis.etapa_detectada);
  const etapaEsperada = normalizar(cultivoData.etapa_siguiente);
  const etapaCoincide = etapaDetectada !== '' && etapaDetectada === etapaEsperada;

  const debeActualizar =
    diagnosis.diagnostico_fallido === false &&
    diagnosis.cambio_confirmado === true &&
    diagnosis.confianza > 0.7 &&
    etapaCoincide;

  // Se prende SOLO cuando la IA respondió bien, afirmó que hubo cambio, y aun
  // así nombró una etapa distinta de la esperada. Es el caso del 17/08
  // ("Fructificación" → el sistema avanzó a Cosecha). No es un fallo de la IA:
  // es evidencia de que el catálogo de etapas se quedó corto (B.1).
  const etapaNoCoincide =
    !etapaCoincide &&
    diagnosis.diagnostico_fallido === false &&
    diagnosis.cambio_confirmado === true;

  // 16.25 — Un único veredicto, calculado acá. La definición vive en el
  // productor (13.4.2): la base no vuelve a decidir, solo ejecuta.
  const resultado =
    diagnosis.diagnostico_fallido === true ? 'diagnostico_fallido' :
    debeActualizar                         ? 'avanza'              :
    etapaNoCoincide                        ? 'etapa_no_coincide'   :
                                             'no_avanza';

  return {
    json: {
      ...cultivoData,
      diagnostico_fenologico: diagnosis,
      etapa_detectada_cruda: diagnosis.etapa_detectada ?? null,
      etapa_no_coincide: etapaNoCoincide,
      debe_actualizar: debeActualizar,
      resultado_evaluacion: resultado,
      nueva_etapa: debeActualizar ? cultivoData.etapa_siguiente : cultivoData.etapa_actual,

      // Cuerpo exacto de la RPC, armado como objeto y no como string, para que
      // el nodo HTTP no tenga que escapar comillas ni interpolar JSON a mano.
      rpc: {
        p_cultivo_id: cultivoData.cultivo_id,
        p_path_foto: cultivoData.ultima_foto_path,
        p_resultado: resultado,
        p_etapas_especie_id_origen: cultivoData.etapas_especie_id ?? null,
        p_etapas_especie_id_destino: cultivoData.etapa_siguiente_etapas_especie_id ?? null,
        p_etapa_destino_id: cultivoData.etapa_siguiente_id ?? null,
        p_etapa_detectada: diagnosis.etapa_detectada ?? null,
        p_confianza: typeof diagnosis.confianza === 'number' ? diagnosis.confianza : null,
        p_diagnostico: diagnosis
      }
    }
  };
});

// Un ítem por cultivo.
// preservan orden y cardinalidad 1:1 INCLUSO AL FALLAR, porque los dos tienen
// `onError: continueRegularOutput` y emiten un ítem de error en la misma posición (16.22).
const fotos = $input.all();
const cultivos = $('Validacion de foto').all();

if (fotos.length !== cultivos.length) {
  throw new Error(
    `Desalineación en Convertir a Base64: ${fotos.length} fotos para ${cultivos.length} cultivos. ` +
    `Emparejar mal una foto con un cultivo produce un diagnóstico atribuido a la planta equivocada.`
  );
}

// 16.22 — Mínimo plausible para un JPEG real, en caracteres de base64.
// No juzga la calidad de la imagen: solo distingue "hay foto usable" de
// "el nodo anterior emitió un ítem de error o un binario vacío".
// 1000 caracteres ≈ 750 bytes: ninguna foto de una planta pesa menos que eso.
const MINIMO_BASE64 = 1000;

return fotos.map((item, i) => {
  let base64 = item.json.foto_base64;
  if (base64 && typeof base64 === 'object' && 'value' in base64) base64 = base64.value;
  if (base64) base64 = base64.trim();

  // Validación POSITIVA por ítem (16.22, mismo criterio que 16.14 y 16.20):
  // confirmar que hay una foto usable, en vez de asumir que "el nodo no explotó"
  // equivale a "la imagen se descargó".
  const fotoOk = typeof base64 === 'string' && base64.length >= MINIMO_BASE64;

  return {
    json: {
      ...cultivos[i].json,
      foto_base64: base64,
      foto_ok: fotoOk,
      motivo_sin_foto: fotoOk
        ? null
        : (item.json?.error?.message ?? item.json?.error ?? 'La foto no se pudo descargar o quedó vacía.')
    }
  };
});

